LiabilityShift decision logic that involves the eci code:

{noformat}        if (threeDSStatus === "failed" || !eci) {
            result.liability_shift_status = LiabilityShiftStatus.NO;
            return result;
        }
        // Refer: https://docs.fondy.eu/en/docs/page/3/#chapter-3-2
        if (gatewayName === "fondy") {
            result.liability_shift_status = ["05", "5", "07", "7"].includes(eci)
                ? LiabilityShiftStatus.YES
                : LiabilityShiftStatus.NO;
            return result;
        }

        // Refer: https://taxify.atlassian.net/wiki/spaces/COMM/pages/3790864474/Liability+Shift#Liability-Shift-Rules
        switch (scheme) {
            case CARD_SCHEME.MASTERCARD: {
                if (["00", "0", "02", "2", "07", "7"].includes(eci) || (["01", "1"].includes(eci) && cavvPresent)) {
                    result.liability_shift_status = LiabilityShiftStatus.YES;
                    return result;
                }
                break;
            }
            case CARD_SCHEME.VISA:
            case CARD_SCHEME.AMEX:
            case CARD_SCHEME.JCB: {
                if (["05", "5"].includes(eci) || (["06", "6"].includes(eci) && cavvPresent)) {
                    result.liability_shift_status = LiabilityShiftStatus.YES;
                    return result;
                }
                break;
            }
        }{noformat}

